//! The runtime of decoders generated from Arm's machine-readable specification (AARCHMRS): the generated tables'
//! types, decision-tree lookup, alias choice and syntax rendering, shared by A64, A32 and T32.
//!
//! Each instruction set's `spec.rs` is generated by `tools/armgen`. What the open-source specification leaves out
//! (how field values become register names, immediates and labels) each set writes by hand, as an operand
//! renderer passed to [`render`].

pub struct Encoding {
    /// The specification's encoding name, such as `ADD_64_addsub_imm`.
    pub name: &'static str,
    pub mask: u32,
    pub value: u32,
    /// Decode condition id for the set's `condition` function; 0 is always true.
    pub condition: u16,
    /// Encoding fields, most significant first.
    pub fields: &'static [Field],
    pub syntax: Syntax,
    pub aliases: &'static [Alias],
}

pub struct Field {
    pub name: &'static str,
    pub start: u8,
    pub width: u8,
}

pub struct Alias {
    /// The alias's operation id, such as `MOV_ADD_addsub_imm`.
    pub name: &'static str,
    /// When the alias applies at all.
    pub condition: u16,
    /// When the alias is the preferred disassembly.
    pub preferred: u16,
    pub syntax: Syntax,
}

pub struct Syntax {
    pub tokens: &'static [Token],
    pub operands: &'static [Operand],
}

pub enum Token {
    Text(&'static str),
    Operand(u8),
    /// Rendered unless every operand inside it is at its default value.
    Optional(&'static [Token]),
    /// The first alternative whose operands can all be rendered.
    Choice(&'static [&'static [Token]]),
}

pub struct Operand {
    /// The placeholder as the specification writes it, such as `<Xd|SP>`.
    pub name: &'static str,
    /// Indices into the encoding's fields, concatenated most significant first.
    pub fields: &'static [u8],
    /// The legal spellings, for operands the grammar defines as a choice (such as the arrangements of `<T>`).
    pub choices: &'static [&'static str],
}

pub enum Node {
    Switch { shift: u8, bits: u8, first: u32 },
    Leaf { first: u32, count: u16 },
}

// Short constructors that keep the generated tables compact.

pub const fn enc(
    name: &'static str,
    mask: u32,
    value: u32,
    condition: u16,
    fields: &'static [Field],
    syntax: Syntax,
    aliases: &'static [Alias],
) -> Encoding {
    Encoding { name, mask, value, condition, fields, syntax, aliases }
}

pub const fn f(name: &'static str, start: u8, width: u8) -> Field {
    Field { name, start, width }
}

pub const fn alias(name: &'static str, condition: u16, preferred: u16, syntax: Syntax) -> Alias {
    Alias { name, condition, preferred, syntax }
}

pub const fn syn(tokens: &'static [Token], operands: &'static [Operand]) -> Syntax {
    Syntax { tokens, operands }
}

pub const fn op(name: &'static str, fields: &'static [u8], choices: &'static [&'static str]) -> Operand {
    Operand { name, fields, choices }
}

pub const fn sw(shift: u8, bits: u8, first: u32) -> Node {
    Node::Switch { shift, bits, first }
}

pub const fn leaf(first: u32, count: u16) -> Node {
    Node::Leaf { first, count }
}

pub use Token::{Choice as Alt, Operand as O, Optional as Opt, Text as T};

/// Processor state some decode conditions read: whether a T32 instruction lies in an IT block.
#[derive(Clone, Copy, Default, PartialEq, Eq, Debug)]
pub struct State {
    pub in_it_block: bool,
}

/// One instruction set's generated tables.
pub struct Tables {
    pub encodings: &'static [Encoding],
    pub nodes: &'static [Node],
    pub candidates: &'static [u16],
    pub condition: fn(u16, u32, State) -> bool,
}

impl Tables {
    /// Finds the encoding of `word`, or `None` when it is unallocated.
    pub fn lookup(&self, word: u32, state: State) -> Option<&'static Encoding> {
        let mut node = &self.nodes[0];
        loop {
            match *node {
                Node::Switch { shift, bits, first } => {
                    let index = (word >> shift) & ((1 << bits) - 1);
                    node = &self.nodes[first as usize + index as usize];
                }
                Node::Leaf { first, count } => {
                    let first = first as usize;
                    let encodings = self.encodings;
                    return self.candidates[first..first + count as usize]
                        .iter()
                        .map(|&index| &encodings[index as usize])
                        .find(|encoding| self.matches(encoding, word, state));
                }
            }
        }
    }

    fn matches(&self, encoding: &Encoding, word: u32, state: State) -> bool {
        word & encoding.mask == encoding.value && (self.condition)(encoding.condition, word, state)
    }

    /// The reference lookup, for tests: every encoding, in specification order.
    #[cfg(test)]
    pub fn lookup_linear(&self, word: u32, state: State) -> Option<&'static Encoding> {
        self.encodings.iter().find(|encoding| self.matches(encoding, word, state))
    }

    /// The syntax to display `encoding` with: its preferred alias, or its own. When several aliases apply (LSL
    /// and UBFIZ both describe some UBFM encodings), the specification lists the more specific one later.
    pub fn preferred_syntax(&self, encoding: &'static Encoding, word: u32, state: State) -> &'static Syntax {
        let applies = |alias: &&Alias| {
            (self.condition)(alias.condition, word, state) && (self.condition)(alias.preferred, word, state)
        };
        encoding.aliases.iter().rev().find(applies).map_or(&encoding.syntax, |alias| &alias.syntax)
    }
}

pub enum Value {
    Text(String),
    /// The operand's default value; an optional group holding only defaults is left out.
    Default(String),
    /// No rendering exists for this encoding; the enclosing alternative does not apply.
    Invalid,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Rendered {
    /// Some operand was printed.
    Shown,
    /// Every operand was at its default value; an optional group around them is left out.
    Default,
    /// An operand has no rendering for this encoding; the enclosing alternative does not apply.
    Invalid,
}

/// Renders `tokens` of `syntax` into `out`, asking `operand` for each operand's text.
pub fn render(operand: &dyn Fn(&Operand) -> Value, syntax: &Syntax, tokens: &[Token], out: &mut String) -> Rendered {
    let mut state = Rendered::Default;
    for token in tokens {
        match token {
            // The specification writes mnemonics and keywords in uppercase; LLVM and GNU tools print lowercase.
            Token::Text(text) => out.extend(text.chars().map(|c| c.to_ascii_lowercase())),
            Token::Operand(index) => match operand(&syntax.operands[*index as usize]) {
                Value::Text(text) => {
                    out.push_str(&text);
                    state = Rendered::Shown;
                }
                Value::Default(text) => out.push_str(&text),
                Value::Invalid => return Rendered::Invalid,
            },
            Token::Optional(inner) => {
                let mut text = String::new();
                if render(operand, syntax, inner, &mut text) == Rendered::Shown {
                    out.push_str(&text);
                    state = Rendered::Shown;
                }
            }
            Token::Choice(alternatives) => {
                let mut chosen = false;
                for alternative in alternatives.iter() {
                    let mut text = String::new();
                    let result = render(operand, syntax, alternative, &mut text);
                    if result != Rendered::Invalid {
                        out.push_str(&text);
                        if result == Rendered::Shown {
                            state = Rendered::Shown;
                        }
                        chosen = true;
                        break;
                    }
                }
                if !chosen {
                    return Rendered::Invalid;
                }
            }
        }
    }
    state
}

/// Renders `syntax`, falling back to `base` (the encoding's own syntax) when an alias cannot show its operands.
/// Returns `None` when neither renders: an operand value outside its legal spellings (a reserved arrangement,
/// say) makes the encoding UNDEFINED. `operand` is called with the syntax being rendered.
pub fn render_with_fallback(
    syntax: &'static Syntax,
    base: &'static Syntax,
    operand: &dyn Fn(&'static Syntax, &Operand) -> Value,
) -> Option<String> {
    for candidate in [syntax, base] {
        let mut out = String::new();
        if render(&|value| operand(candidate, value), candidate, candidate.tokens, &mut out) != Rendered::Invalid {
            return Some(out.trim_end().to_owned());
        }
    }
    None
}
